<?php
require_once __DIR__.'/../Services/Auditoria.php';
require_once __DIR__.'/Caja.php';
require_once __DIR__.'/Producto.php';
require_once __DIR__.'/ReporteVenta.php';
class Gasto
{
    private $db;
    public function __construct(PDO $db){$this->db=$db;}
    private function query($sql,array $args=array()){$q=$this->db->prepare($sql);$q->execute($args);return $q->fetchAll();}
    private function hoy(){return (new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('Y-m-d');}
    private function actor($id,$permiso){$this->db->query('SELECT id FROM roles ORDER BY id FOR SHARE')->fetchAll();$q=$this->db->prepare('SELECT id FROM usuarios WHERE id=? FOR UPDATE');$q->execute(array($id));$q->fetchColumn();$a=(new Usuario($this->db))->buscar($id);if(!$a||!$a['activo']||(empty($a['permisos']['todo'])&&(empty($a['permisos'][$permiso])||empty($a['permisos']['ver_gastos']))))throw new HttpError('No tienes permiso para esta operación.',403);return $a;}
    public function categorias(){
        $rows=$this->db->query('SELECT id,nombre,activo FROM categorias_gasto ORDER BY nombre,id')->fetchAll();foreach($rows as &$r)$r['version']=hash('sha256',json_encode($r));unset($r);return $rows;
    }
    public function categoria(array $d,$actorId,$id=null){
        $name=Producto::texto($d,'nombre',80,true);if(preg_match('/[\x00-\x1f\x7f]/u',$name))throw new HttpError('Escribe un nombre sin saltos de línea.');$active=isset($d['activo'])?$d['activo']:1;if(!in_array($active,array(0,1,'0','1',true,false),true))throw new HttpError('Estado no válido.');
        $this->db->beginTransaction();try{$this->actor($actorId,'todo');if($id!==null){$rows=$this->query('SELECT id,nombre,activo FROM categorias_gasto WHERE id=? FOR UPDATE',array($id));if(!$rows)throw new HttpError('Categoría no encontrada.',404);$version=hash('sha256',json_encode($rows[0]));if(!isset($d['version'])||!is_string($d['version'])||!hash_equals($version,$d['version']))throw new HttpError('La categoría cambió. Vuelve a consultarla.',409);}
            $q=$this->db->prepare('SELECT id FROM categorias_gasto WHERE nombre=? AND id<>?');$q->execute(array($name,$id===null?0:$id));if($q->fetchColumn())throw new HttpError('Ya existe una categoría con ese nombre.',409);
            if($id===null){$this->db->prepare('INSERT INTO categorias_gasto(nombre,activo) VALUES (?,?)')->execute(array($name,(int)$active));$id=$this->db->lastInsertId();}else $this->db->prepare('UPDATE categorias_gasto SET nombre=?,activo=? WHERE id=?')->execute(array($name,(int)$active,$id));$this->db->commit();return array('id'=>$id);
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&$e->getCode()==='23000')throw new HttpError('Ya existe una categoría con ese nombre.',409);throw $e;}
    }
    public function catalogos(array $actor){return array('hoy'=>$this->hoy(),'todos'=>!empty($actor['permisos']['todo']),'puede_registrar'=>!empty($actor['permisos']['todo'])||!empty($actor['permisos']['registrar_gastos']),'puede_caja'=>!empty($actor['permisos']['todo'])||!empty($actor['permisos']['operar_caja']),'categorias'=>$this->categorias(),'metodos'=>$this->db->query("SELECT id,nombre,tipo FROM metodos_pago WHERE activo=1 AND tipo<>'credito' ORDER BY id")->fetchAll(),'turnos'=>$this->query("SELECT t.id,c.nombre caja FROM turnos_caja t JOIN cajas c ON c.id=t.caja_id JOIN ubicaciones l ON l.id=COALESCE(t.ubicacion_id,c.ubicacion_id) WHERE t.abierto_por=? AND t.estatus='abierto' AND c.activo=1 AND l.activo=1 AND l.disponible_venta=1",array($actor['id'])));}
    public function listar(array $d,array $actor){
        $f=(new ReporteVenta($this->db))->filtros($d,$actor);$where='g.fecha>=? AND g.fecha<?';$args=array($f['desde'],$f['fin']);if($f['usuario_id']!==null){$where.=' AND g.usuario_id=?';$args[]=$f['usuario_id'];}
        $category=Producto::identificador(isset($d['categoria_id'])&&$d['categoria_id']!==''?$d['categoria_id']:null,true);if($category!==null){$where.=' AND g.categoria_id=?';$args[]=$category;}$origin=isset($d['origen'])?$d['origen']:'';if(!in_array($origin,array('','caja','externo'),true))throw new HttpError('Origen no válido.');if($origin!==''){$where.=' AND g.origen=?';$args[]=$origin;}
        if($f['caja_id']!==null){$where.=' AND t.caja_id=?';$args[]=$f['caja_id'];}$search=Producto::texto($d,'buscar',100,false);if($search!==''){$like='%'.str_replace(array('!','%','_'),array('!!','!%','!_'),$search).'%';$where.=" AND (g.folio LIKE ? ESCAPE '!' OR g.descripcion LIKE ? ESCAPE '!' OR g.beneficiario LIKE ? ESCAPE '!')";array_push($args,$like,$like,$like);}
        $base=' FROM gastos g JOIN categorias_gasto c ON c.id=g.categoria_id LEFT JOIN turnos_caja t ON t.id=g.turno_id WHERE '.$where;$this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{
            $summary=$this->query("SELECT COUNT(*) registros,CAST(COALESCE(SUM(g.monto),0) AS DECIMAL(24,2)) total,CAST(COALESCE(SUM(IF(g.origen='caja',g.monto,0)),0) AS DECIMAL(24,2)) caja,CAST(COALESCE(SUM(IF(g.origen='externo',g.monto,0)),0) AS DECIMAL(24,2)) externo".$base,$args)[0];$groups=$this->query('SELECT c.id,c.nombre,COUNT(*) registros,CAST(SUM(g.monto) AS DECIMAL(24,2)) total'.$base.' GROUP BY c.id,c.nombre ORDER BY total DESC,c.id',$args);
            if(isset($d['antes_de'])&&$d['antes_de']!==''){$base.=' AND g.id<?';$args[]=Producto::identificador($d['antes_de']);}$rows=$this->query('SELECT g.id,g.folio,g.fecha,g.monto,g.origen,g.descripcion,g.beneficiario,g.datos'.$base.' ORDER BY g.id DESC LIMIT 31',$args);$more=count($rows)>30;if($more)array_pop($rows);foreach($rows as &$r)$r['datos']=json_decode($r['datos'],true);unset($r);$this->db->commit();return array('filtros'=>array_diff_key($f,array('fin'=>true)),'resumen'=>$summary,'categorias'=>$groups,'gastos'=>$rows,'siguiente'=>$more?$rows[count($rows)-1]['id']:null);
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function obtener($id,array $actor){$rows=$this->query('SELECT *,UNIX_TIMESTAMP(creado_en) creado_unix FROM gastos WHERE id=?',array($id));if(!$rows)throw new HttpError('Gasto no encontrado.',404);$g=$rows[0];if(empty($actor['permisos']['todo'])&&(string)$actor['id']!==(string)$g['usuario_id'])throw new HttpError('Solo puedes consultar tus propios gastos.',403);unset($g['clave'],$g['huella']);$g['datos']=json_decode($g['datos'],true);return $g;}
    public function registrar(array $d,$actorId){
        $origin=isset($d['origen'])?$d['origen']:null;if(!in_array($origin,array('caja','externo'),true))throw new HttpError('Indica el origen del dinero.');$turn=$origin==='caja'?Producto::identificador(isset($d['turno_id'])?$d['turno_id']:null):null;$method=Producto::identificador(isset($d['metodo_pago_id'])?$d['metodo_pago_id']:null);$category=Producto::identificador(isset($d['categoria_id'])?$d['categoria_id']:null);$n=Caja::centavos(isset($d['monto'])?$d['monto']:null);if(!$n)throw new HttpError('El importe debe ser mayor que cero.');$fecha=isset($d['fecha'])?$d['fecha']:null;$date=is_string($fecha)?DateTimeImmutable::createFromFormat('!Y-m-d',$fecha):false;if(!$date||$date->format('Y-m-d')!==$fecha||$fecha<'2023-01-01'||$fecha>$this->hoy())throw new HttpError('Selecciona una fecha de gasto válida, sin fechas futuras.');
        $account=$origin==='externo'?Producto::texto($d,'cuenta',100,true):null;$beneficiary=Producto::texto($d,'beneficiario',150,false);$description=Producto::texto($d,'descripcion',300,true);$reference=Producto::texto($d,'referencia',100,false);$key=isset($d['clave'])?$d['clave']:'';if(!is_string($key)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/D',$key))throw new HttpError('Recarga el formulario del gasto.');$hash=hash('sha256',json_encode(array($origin,$turn,$method,$category,$n,$fecha,$account,$beneficiary,$description,$reference)));
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
            $actor=$this->actor($actorId,'registrar_gastos');$q=$this->db->prepare('SELECT id,folio,monto,huella FROM gastos WHERE usuario_id=? AND clave=?');$q->execute(array($actorId,$key));$old=$q->fetch();if($old){if(!hash_equals($old['huella'],$hash))throw new HttpError('La solicitud ya se utilizó con otros datos.',409);$this->db->commit();return array('id'=>$old['id'],'folio'=>$old['folio'],'monto'=>$old['monto']);}
            $t=null;if($origin==='caja'){
                if($fecha!==$this->hoy())throw new HttpError('El efectivo de caja se registra con la fecha de hoy.');if(empty($actor['permisos']['todo'])&&empty($actor['permisos']['operar_caja']))throw new HttpError('Necesitas permiso para operar caja.',403);$q=$this->db->prepare('SELECT caja_id FROM turnos_caja WHERE id=?');$q->execute(array($turn));$box=$q->fetchColumn();if(!$box)throw new HttpError('Turno no encontrado.',404);$q=$this->db->prepare('SELECT id FROM cajas WHERE id=? FOR UPDATE');$q->execute(array($box));$q->fetchColumn();$q=$this->db->prepare('SELECT * FROM turnos_caja WHERE id=? FOR UPDATE');$q->execute(array($turn));$t=$q->fetch();if($t['estatus']!=='abierto'||(string)$t['abierto_por']!==(string)$actorId)throw new HttpError('Usa tu propio turno abierto.',403);$rows=$this->query('SELECT c.nombre caja,c.activo,l.activo ubicacion_activa,l.disponible_venta FROM cajas c JOIN ubicaciones l ON l.id=COALESCE(?,c.ubicacion_id) WHERE c.id=?',array($t['ubicacion_id'],$box));$b=$rows[0];if(!$b['activo']||!$b['ubicacion_activa']||!$b['disponible_venta'])throw new HttpError('La caja y su ubicación deben estar habilitadas.',409);$t['caja_nombre']=$b['caja'];
            }
            $rows=$this->query('SELECT id,nombre,activo FROM categorias_gasto WHERE id=? FOR SHARE',array($category));if(!$rows||!$rows[0]['activo'])throw new HttpError('Selecciona una categoría activa.');$cat=$rows[0];$rows=$this->query('SELECT id,nombre,tipo,activo FROM metodos_pago WHERE id=? FOR SHARE',array($method));if(!$rows||!$rows[0]['activo']||$rows[0]['tipo']==='credito')throw new HttpError('Selecciona un método activo distinto de crédito.');$m=$rows[0];if($origin==='caja'&&$m['tipo']!=='efectivo')throw new HttpError('La caja solo entrega efectivo. Usa fondos externos para otro método.');if($origin==='caja'){$cash=(new Caja($this->db))->resumenBloqueado($t);if($n>max(0,Caja::centavos($cash['esperado'],true)))throw new HttpError('No hay efectivo suficiente en tu caja.',409);}
            $data=array('usuario'=>$actor['nombre'],'categoria'=>$cat['nombre'],'metodo'=>$m['nombre'],'caja'=>$t?$t['caja_nombre']:null);$this->db->prepare('INSERT INTO gastos(folio,categoria_id,usuario_id,turno_id,metodo_pago_id,tipo_metodo,origen,fecha,monto,cuenta,beneficiario,descripcion,referencia,clave,huella,datos) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute(array('P-'.bin2hex(random_bytes(10)),$category,$actorId,$turn,$method,$m['tipo'],$origin,$fecha,Caja::dinero($n),$account,$beneficiary,$description,$reference,$key,$hash,json_encode($data)));$id=$this->db->lastInsertId();$folio='G-'.str_pad($id,8,'0',STR_PAD_LEFT);$movement=null;
            if($origin==='caja'){$this->db->prepare("INSERT INTO movimientos_efectivo(turno_id,tipo,monto,motivo,usuario_id) VALUES (?,'salida',?,?,?)")->execute(array($turn,Caja::dinero($n),$folio.' · Gasto: '.preg_replace('/^(.{0,140}).*$/us', '$1', $description),$actorId));$movement=$this->db->lastInsertId();}
            $this->db->prepare('UPDATE gastos SET folio=?,movimiento_id=? WHERE id=?')->execute(array($folio,$movement,$id));Auditoria::operacion($this->db,'gasto',$id);$this->db->commit();return array('id'=>$id,'folio'=>$folio,'monto'=>Caja::dinero($n));
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
